1	import { readFile } from "node:fs/promises";
2	import { dirname, relative, resolve } from "node:path";
3	import { fileURLToPath } from "node:url";
4	import { canonicalJson, canonicalText, compareCodePoint, sha256 } from "./canonicalize.mjs";
5	import { fail } from "./errors.mjs";
6	import { assertNoCaseFoldCollisions, normalizeRelativePath, resolveContainedFile, resolveContainedFileFrom, sourceRootFor } from "./paths.mjs";
7	
8	const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
9	
10	export function validateJsonSchema(value, schema, at = "$") {
11	  const errors = [];
12	  const visit = (current, rule, path) => {
13	    if (rule.oneOf) {
14	      const candidates = rule.oneOf.map((candidate) => {
15	        const before = errors.length;
16	        visit(current, candidate, path);
17	        const result = errors.splice(before);
18	        return result;
19	      });
20	      const passing = candidates.filter((candidate) => candidate.length === 0).length;
21	      if (passing !== 1) errors.push(`${path} must match exactly one allowed shape`);
22	      return;
23	    }
24	    if (Object.hasOwn(rule, "const") && canonicalJson(current) !== canonicalJson(rule.const)) errors.push(`${path} must equal ${JSON.stringify(rule.const)}`);
25	    if (rule.enum && !rule.enum.some((item) => canonicalJson(item) === canonicalJson(current))) errors.push(`${path} is not an allowed value`);
26	    if (rule.type) {
27	      const actual = current === null ? "null" : Array.isArray(current) ? "array" : Number.isInteger(current) ? "integer" : typeof current;
28	      const typeMatches = rule.type === actual || (rule.type === "number" && typeof current === "number");
29	      if (!typeMatches) {
30	        errors.push(`${path} must be ${rule.type}`);
31	        return;
32	      }
33	    }
34	    if (typeof current === "string") {
35	      if (rule.minLength !== undefined && current.length < rule.minLength) errors.push(`${path} is too short`);
36	      if (rule.pattern && !new RegExp(rule.pattern, "u").test(current)) errors.push(`${path} does not match ${rule.pattern}`);
37	    }
38	    if (typeof current === "number" && rule.minimum !== undefined && current < rule.minimum) errors.push(`${path} is below minimum`);
39	    if (Array.isArray(current)) {
40	      if (rule.minItems !== undefined && current.length < rule.minItems) errors.push(`${path} has too few items`);
41	      if (rule.uniqueItems) {
42	        const keys = current.map(canonicalJson);
43	        if (new Set(keys).size !== keys.length) errors.push(`${path} has duplicate items`);
44	      }
45	      if (rule.items) current.forEach((item, index) => visit(item, rule.items, `${path}[${index}]`));
46	    }
47	    if (current && typeof current === "object" && !Array.isArray(current)) {
48	      const keys = Object.keys(current);
49	      if (rule.minProperties !== undefined && keys.length < rule.minProperties) errors.push(`${path} has too few properties`);
50	      for (const required of rule.required ?? []) if (!Object.hasOwn(current, required)) errors.push(`${path}.${required} is required`);
51	      if (rule.propertyNames?.pattern) {
52	        const pattern = new RegExp(rule.propertyNames.pattern, "u");
53	        for (const key of keys) if (!pattern.test(key)) errors.push(`${path} property ${key} is invalid`);
54	      }
55	      for (const key of keys) {
56	        if (rule.properties?.[key]) visit(current[key], rule.properties[key], `${path}.${key}`);
57	        else if (rule.additionalProperties === false) errors.push(`${path}.${key} is not allowed`);
58	        else if (rule.additionalProperties && typeof rule.additionalProperties === "object") visit(current[key], rule.additionalProperties, `${path}.${key}`);
59	      }
60	    }
61	  };
62	  visit(value, schema, at);
63	  return errors;
64	}
65	
66	export async function readJsonFile(path, logicalPath = path) {
67	  const bytes = await readFile(path);
68	  const text = canonicalText(bytes, logicalPath);
69	  let value;
70	  try {
71	    value = JSON.parse(text);
72	  } catch (error) {
73	    fail("JSON_INVALID", `${logicalPath} is not valid JSON: ${error.message}`, "Correct the canonical JSON source.");
74	  }
75	  assertNoDuplicateJsonKeys(text, logicalPath);
76	  return { value, text, bytes: Buffer.from(text, "utf8") };
77	}
78	
79	function assertNoDuplicateJsonKeys(text, logicalPath) {
80	  let index = 0;
81	  const whitespace = () => { while (/\s/u.test(text[index] ?? "")) index += 1; };
82	  const string = () => {
